<template><div class="community-page"><header class="page-heading"><div><div class="page-eyebrow">APPEAL REVIEW</div><h1>申诉中心</h1><p>复核被处理对象提交的举报申诉。</p></div><n-button :loading="loading" @click="load">刷新</n-button></header><n-card><n-alert v-if="error" type="error" style="margin-bottom:16px">{{ error }}</n-alert><n-empty v-if="!loading && rows.length === 0" description="暂无待复核申诉"/><n-data-table v-else :columns="columns" :data="rows" :loading="loading" :row-key="(row: CommunityAppeal) => row.id"/></n-card></div></template>
<script setup lang="ts">import { h,onMounted,ref } from 'vue'; import { NButton,NTag,NSpace,useDialog,useMessage } from 'naive-ui'; import { communityApi,type CommunityAppeal } from '@/api/community'; const rows=ref<CommunityAppeal[]>([]),loading=ref(false),error=ref(''),message=useMessage(),dialog=useDialog(); const columns=[{title:'举报',key:'reportId'},{title:'状态',key:'status',render:(row:CommunityAppeal)=>h(NTag,{type:'warning'},{default:()=>row.status})},{title:'操作',key:'actions',render:(row:CommunityAppeal)=>h(NSpace,{}, {default:()=>[h(NButton,{size:'small',type:'success',onClick:()=>review(row,false)},{default:()=> '维持'}),h(NButton,{size:'small',onClick:()=>review(row,true)},{default:()=> '撤销'})]})}]; async function load(){loading.value=true;error.value='';try{rows.value=await communityApi.appeals()}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}} function review(row:CommunityAppeal,revoke:boolean){dialog.warning({title:revoke?'撤销原决定':'维持原决定',content:'请确认本次申诉复核结果。',positiveText:'确认',negativeText:'取消',onPositiveClick:async()=>{try{await communityApi.reviewAppeal(row.id,row.lockVersion,revoke,revoke?'申诉复核后撤销原决定':'申诉复核后维持原决定');message.success('复核完成');load()}catch(e){message.error(e instanceof Error?e.message:'复核失败')}}})} onMounted(load)</script>
<style scoped>.community-page{padding:24px}.page-heading{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px}.page-eyebrow{font-size:12px;font-weight:600;letter-spacing:.5px;color:var(--community-muted);margin-bottom:8px}.page-heading h1{font-size:24px;margin:0 0 8px}.page-heading p{margin:0;color:var(--community-muted)}</style>
